body.script:
(()=>{
'use strict';
const EMBED=document.documentElement.classList.contains('embed')||/[?&]embed(?:=|&|$)/.test(location.search)||!!window.QUEST_EMBED;
if(EMBED){
  document.documentElement.classList.add('embed');
  document.querySelectorAll('link[href*="fonts.google"]').forEach(n=>n.remove());
}

/* ============ palette (all colors live here — nudge to match a reference shot) ============ */
const C = {
  navy:'#011F3B', cream:'#FCFEFC',
  sky:'#B9E6F4', haze1:'#E6F6F6', haze2:'#FCFEFC',
  mtnFar:'#9BB8C8', mtnNear:'#7A9AAE', snow:'#FCFEFC',
  grass:['#7EC86A','#6FBE62','#8ED176','#68B85C','#76C46A','#88D078','#5FB056','#82CC70'],
  grassFar:'#C8EBB0', hill:'#6FBE62', hillHi:'#A8E08A',
  sunTint:'#F4B942', shadeTint:'#2F7D5A',
  waterEdge:'#0E7A7C', water:'#159A9C', waterLight:'#8ED5D6', foam:'#FCFEFC',
  sea:'#3DB4C8', seaLight:'#7ED4E0',
  sand:'#F6E7C8', sandRim:'#E6D7B8', shell:'#F8E7DF', shellEdge:'#E87524',
  pathShadow:'rgba(1,31,59,.16)', pathEdge:'#E2CFA4', path:'#FFF6DE', pebble:'#F6E7C8',
  trunk:'#704A2E', wood:'#8A5A38', woodDark:'#5C3A22', woodMid:'#7A4E30', post:'#704A2E',
  rockA:'#C9D0CE', rockB:'#D9EBD4', rockHi:'#FCFEFC',
  stoneDeck:'#FFFDF7', stoneEdge:'#D9C7A0', stoneBlock:'#F6E7C8',
  castleWall:'#FFFDF7', castleStroke:'#E6D7B8', roofRed:'#E87524', roofRedD:'#C4621C',
  turret:'#159A9C', turretD:'#0E7A7C', flag:'#E87524',
  wall1:'#FCFEFC', wall2:'#FFFDF7', wall3:'#F8E7DF', wall4:'#E9F4EC',
  roofTeal:'#159A9C', roofTealD:'#0E7A7C', roofTan:'#F4B942', roofTanD:'#D4A02E',
  door:'#704A2E', glass:'#E6F6F6',
  pineA:'#2F7D5A', pineB:'#3F8A64', pineC:'#6FBE62',
  lily:'#2F7D5A', reed:'#3F8A64', reedTip:'#F4B942',
  lhRed:'#E87524', lhCap:'#C4621C', lamp:'#F4B942',
  hay:'#F4B942', hayEdge:'#D4A02E',
  orange:'#E87524', gold:'#F4B942', teal:'#159A9C', forest:'#2F7D5A',
  brick:'#E8C49A', brickAlt:'#D0925A', brickDeep:'#C4621C', grout:'#8A5A38',
  shadow:'rgba(1,31,59,.18)', waterShadow:'rgba(1,31,59,.22)',
};
const PAL = [
  {wall:C.wall1, roof:C.roofRed,  roofD:C.roofRedD},
  {wall:C.wall2, roof:C.roofTeal, roofD:C.roofTealD},
  {wall:C.wall3, roof:C.roofRed,  roofD:C.roofRedD},
  {wall:C.wall4, roof:C.roofTan,  roofD:C.roofTanD},
];
const FLOWER_COLS=[['#E87524','#F4B942'],['#FCFEFC','#F4B942'],['#F4B942','#E87524'],['#159A9C','#F4B942'],['#F8E7DF','#E87524']];
const TREE_COLS=[['#2F7D5A','#4F9A72'],['#3A7F5F','#6FBE62'],['#2A6E50','#8ED176']];

/* ============ tiny toolkit ============ */
const NS='http://www.w3.org/2000/svg';
const W=1000, H=24000;
const CHUNK=2000, CHUNKS=H/CHUNK, SEED=987654321;
let chunkY0=0, chunkY1=H;
const vis=(y,pad=200)=>y>=chunkY0-pad && y{const prev=SKIP;SKIP=!vis(y,pad);fn();SKIP=prev;};
let _s=SEED;
const rnd=()=>{_s=_s+0x6D2B79F5|0;let t=Math.imul(_s^_s>>>15,1|_s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};
const R=(a,b)=>a+(b-a)*rnd();
const RI=(a,b)=>Math.floor(R(a,b+1));
const pick=a=>a[Math.floor(rnd()*a.length)];
const f1=n=>(+n).toFixed(1);
const lerp=(a,b,t)=>a+(b-a)*t;
const hexLerp=(h1,h2,t)=>{
  const c=h=>[parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)];
  const a=c(h1),b=c(h2);
  return 'rgb('+a.map((v,i)=>Math.round(lerp(v,b[i],t))).join(',')+')';
};

let SKIP=false;
const NOP={setAttribute(){},appendChild(){},style:{}};
const E=(t,a={},p)=>{
  if(SKIP) return NOP;
  const n=document.createElementNS(NS,t);for(const k in a)n.setAttribute(k,a[k]);if(p)p.appendChild(n);return n;
};
const grp=(p,a={})=>E('g',a,p);
const path=(p,d,a={})=>E('path',{d,...a},p);
const circ=(p,cx,cy,r,a={})=>E('circle',{cx:f1(cx),cy:f1(cy),r:f1(r),...a},p);
const ell=(p,cx,cy,rx,ry,a={})=>E('ellipse',{cx:f1(cx),cy:f1(cy),rx:f1(rx),ry:f1(ry),...a},p);
const rrect=(p,x,y,w,h,rx,a={})=>E('rect',{x:f1(x),y:f1(y),width:f1(w),height:f1(h),rx:f1(rx),...a},p);
const circSub=(cx,cy,r)=>`M${f1(cx-r)} ${f1(cy)}a${f1(r)} ${f1(r)} 0 1 0 ${f1(2*r)} 0a${f1(r)} ${f1(r)} 0 1 0 ${f1(-2*r)} 0`;
const ellSub=(cx,cy,rx,ry)=>`M${f1(cx-rx)} ${f1(cy)}a${f1(rx)} ${f1(ry)} 0 1 0 ${f1(2*rx)} 0a${f1(rx)} ${f1(ry)} 0 1 0 ${f1(-2*rx)} 0`;

function smoothPts(pts){
  let d=`M${f1(pts[0][0])} ${f1(pts[0][1])}`;
  for(let i=1;i<pts.length-1;i++){
    const mx=(pts[i][0]+pts[i+1][0])/2, my=(pts[i][1]+pts[i+1][1])/2;
    d+=`Q${f1(pts[i][0])} ${f1(pts[i][1])} ${f1(mx)} ${f1(my)}`;
  }
  d+=`L${f1(pts[pts.length-1][0])} ${f1(pts[pts.length-1][1])}`;
  return d;
}
function blob(cx,cy,rx,ry,irr=.09,n=12){
  const P=[],ph=R(0,6.283);
  for(let i=0;i<n;i++){const a=i/n*6.283;
    const rr=1+irr*Math.sin(3*a+ph)+irr*.6*Math.sin(5*a+ph*2);
    P.push([cx+Math.cos(a)*rx*rr, cy+Math.sin(a)*ry*rr]);}
  let d=`M${f1((P[0][0]+P[1][0])/2)} ${f1((P[0][1]+P[1][1])/2)}`;
  for(let i=1;i<=n;i++){const p=P[i%n],q=P[(i+1)%n];
    d+=`Q${f1(p[0])} ${f1(p[1])} ${f1((p[0]+q[0])/2)} ${f1((p[1]+q[1])/2)}`;}
  return d+'Z';
}
/* Catmull-Rom → cubic Bézier, with dense samples for geometry queries */
function spline(pts,steps=14,withW=false){
  const P=[pts[0],...pts,pts[pts.length-1]];
  let d=`M${f1(pts[0][0])} ${f1(pts[0][1])}`;
  const S=[];const push=(x,y,w)=>S.push(withW?{x,y,w}:{x,y});
  push(pts[0][0],pts[0][1],pts[0][2]||0);
  for(let i=0;i<pts.length-1;i++){
    const p0=P[i],p1=P[i+1],p2=P[i+2],p3=P[i+3];
    const c1x=p1[0]+(p2[0]-p0[0])/6, c1y=p1[1]+(p2[1]-p0[1])/6;
    const c2x=p2[0]-(p3[0]-p1[0])/6, c2y=p2[1]-(p3[1]-p1[1])/6;
    d+=`C${f1(c1x)} ${f1(c1y)} ${f1(c2x)} ${f1(c2y)} ${f1(p2[0])} ${f1(p2[1])}`;
    for(let s=1;s<=steps;s++){
      const t=s/steps,u=1-t;
      push(u*u*u*p1[0]+3*u*u*t*c1x+3*u*t*t*c2x+t*t*t*p2[0],
           u*u*u*p1[1]+3*u*u*t*c1y+3*u*t*t*c2y+t*t*t*p2[1],
           lerp(p1[2]||0,p2[2]||0,t));
    }
  }
  return {d,S};
}
function makeGrid(S,cell=150){
  const g=new Map();S.forEach(s=>{const k=Math.floor(s.y/cell);
    if(!g.has(k))g.set(k,[]);g.get(k).push(s);});
  return {g,cell,S};
}
function nearest(grid,x,y){
  const k=Math.floor(y/grid.cell);let best=1e9,bx=0,by=0,bw=0;
  for(let j=k-2;j<=k+2;j++){const a=grid.g.get(j);if(!a)continue;
    for(const s of a){const d=Math.hypot(s.x-x,s.y-y);if(d<best){best=d;bx=s.x;by=s.y;bw=s.w||0;}}}
  if(best===1e9){for(const s of grid.S){const d=Math.hypot(s.x-x,s.y-y);if(d{const p=roadPoint(i/127);return [p.x,p.y];});
const BRIDGES=[
  {y:4960,style:'wood'},
  {y:13760,style:'wood'},
  {y:20460,style:'stone'},
];
const inBridgeZone=y=>BRIDGES.some(b=>Math.abs(y-b.y)<230);

const pathSpl=spline(PW,14);
const pathD=pathSpl.d, pathS=pathSpl.S;
const pathGrid=makeGrid(pathS);
const distPath=(x,y)=>nearest(pathGrid,x,y).d;
function pathAtY(y){
  for(let i=0;i<pathS.length-1;i++){const a=pathS[i],b=pathS[i+1];
    const lo=Math.min(a.y,b.y),hi=Math.max(a.y,b.y);
    if(yhi)continue;
    const t=(y-a.y)/((b.y-a.y)||1);
    return {x:lerp(a.x,b.x,t),ang:Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI};}
  const n=pathS.length;return {x:pathS[n-1].x,ang:90};
}

function riverAtY(y){
  return {x:pathAtY(y).x,w:80};
}

/* water samples (streams / remaining water) power the clearance engine */
const waterS=[];
let waterGrid=null;
const buildWaterGrid=()=>{waterGrid=makeGrid(waterS);};
const distWater=(x,y)=>{
  if(!waterGrid||!waterGrid.S.length)return 1e9;
  const n=nearest(waterGrid,x,y);return n.d-(n.w||0)/2-4;
};

/* ============ clearance engine: keep the road node-friendly ============ */
const placed=[];
const register=(x,y,r)=>placed.push({x,y,r});
function free(x,y,r,o={}){
  if(xW-r-14||yH-r-14)return false;
  if(y<1600||y>22760)return false;                        // stay off sky and shore
  if(distPath(x,y)<(o.padPath??62)+r)return false;       // keep the cream trail clear
  if(distWater(x,y)<(o.rivPad??14)+r)return false;       // never sit in water
  for(const q of placed){if(Math.hypot(q.x-x,q.y-y)<q.r+r+14)return false;}
  return true;
}

/* ============ scene layers (painter's order) ============ */
let sky,mtn,clouds,land,tint,coast,water,fences,flora,marks,sparkles;

function paintChunk(host,y0,y1){
_s=SEED;
placed.length=0;
waterS.length=0;
SKIP=false;
chunkY0=y0;chunkY1=y1;
host.replaceChildren();
const defs=E('defs',{},host);
const clip=E('clipPath',{id:'c'+y0},defs);
E('rect',{x:0,y:y0,width:W,height:y1-y0},clip);
const scene=grp(host,{'clip-path':'url(#c'+y0+')'});
sky=grp(scene); mtn=grp(scene); clouds=grp(scene);
land=grp(scene); tint=grp(scene); coast=grp(scene); water=grp(scene);
fences=grp(scene); flora=grp(scene); marks=grp(scene);
sparkles=grp(scene);

/* ---------- sky, mountains, clouds ---------- */
const mPath=(pts,cy)=>{let d=`M${pts[0][0]} ${pts[0][1]}`;
  for(let i=1;i<pts.length-1;i++){const mx=(pts[i][0]+pts[i+1][0])/2,my=(pts[i][1]+pts[i+1][1])/2;
    d+=`Q${pts[i][0]} ${pts[i][1]} ${mx} ${my}`;}
  d+=`L${pts[pts.length-1][0]} ${pts[pts.length-1][1]}L1080 ${cy}L-80 ${cy}Z`;return d;};
if(chunkY0<1600){
E('rect',{x:-80,y:0,width:1160,height:1580,fill:C.sky},sky);
ell(sky,500,1280,640,260,{fill:C.haze1,opacity:.55});
ell(sky,500,1336,430,168,{fill:C.haze2,opacity:.5});
path(mtn,mPath([[-80,1280],[130,904],[240,1130],[380,824],[500,1090],[640,924],[760,1150],[880,936],[1080,1176]],1320),{fill:C.mtnFar});
[[130,904],[380,824],[640,924],[880,936]].forEach(([x,y])=>{
  path(mtn,`M${x-17} ${y+16}Q${x} ${y-8} ${x+17} ${y+16}Q${x} ${y+24} ${x-17} ${y+16}Z`,{fill:C.snow});});
path(mtn,mPath([[-80,1320],[90,1080],[190,1224],[320,1004],[450,1244],[590,1044],[720,1256],[830,1096],[1080,1284]],1336),{fill:C.mtnNear});
[[612,336,1],[668,410,.82],[722,304,.9]].forEach(([bx,by,s])=>{
  path(sky,`M${f1(bx-12*s)} ${f1(by)}Q${f1(bx-6*s)} ${f1(by-8*s)} ${f1(bx)} ${f1(by)}Q${f1(bx+6*s)} ${f1(by-8*s)} ${f1(bx+12*s)} ${f1(by)}`,
    {stroke:C.navy,'stroke-width':2.6,fill:'none','stroke-linecap':'round',opacity:.45});});
}
[[170,280,1.15],[560,170,.85],[840,450,1.25],[95,660,.7],[700,830,.95],[915,210,.65]].forEach(([cx,cy,s],i)=>{
  withVis(cy,80,()=>{
    const g=grp(clouds,{class:'cloud'});
    g.style.animationDuration=(26+i*5)+'s';g.style.animationDelay=(-R(0,20))+'s';
    ell(g,cx,cy,46*s,15*s,{fill:C.cream,opacity:.97});
    circ(g,cx-24*s,cy-9*s,15*s,{fill:C.cream});
    circ(g,cx+2*s,cy-15*s,20*s,{fill:C.cream});
    circ(g,cx+26*s,cy-8*s,13*s,{fill:C.cream});
  });
});
[[210,350,1],[470,236,.85],[690,410,.95],[860,176,.7]].forEach(([bx,by,s])=>{
  withVis(by,40,()=>bird(bx,by,s));
});

/* ---------- land: base, castle hill, rolling bands, light ---------- */
E('rect',{x:-80,y:Math.max(1236,chunkY0),width:1160,height:Math.max(0,chunkY1-Math.max(1236,chunkY0)),fill:C.grass[0]},land);
if(chunkY0<1600){
path(land,'M20 1440C110 1080 150 500 300 410C450 500 490 1080 580 1440Z',{fill:C.hill});
ell(land,292,664,150,144,{fill:C.hillHi,opacity:.45});
}
let bi=0;
for(let y=1320;y<=23400;y+=400){
  const amp=R(24,58),ph=R(0,6.283),frq=R(1.8,3.2);
  const pts=[];for(let x=-80;x<=1080;x+=62)
    pts.push([x,y+Math.sin(ph+x/1000*6.283*frq)*amp+R(-8,8)]);
  let d=`M-80 ${chunkY1+48}L-80 ${f1(pts[0][1])}`;
  for(let i=0;i<pts.length-1;i++){
    const mx=(pts[i][0]+pts[i+1][0])/2,my=(pts[i][1]+pts[i+1][1])/2;
    d+=`Q${f1(pts[i][0])} ${f1(pts[i][1])} ${f1(mx)} ${f1(my)}`;}
  d+=`L1080 ${chunkY1+48}Z`;
  const col=bi<4?hexLerp(C.grassFar,C.grass[(bi*3)%8],.35+bi*.15):C.grass[(bi*5+RI(0,1)*2)%8];
  if(y<chunkY1+80) path(land,d,{fill:col});
  bi++;
}
for(let i=0;i<26;i++){                                   // gentle sun / shade patches
  const x=R(70,930),y=R(1520,22680),rx=R(90,180),ry=rx*R(.3,.5),rot=R(-9,9);
  const light=rnd()<.58;
  if(vis(y,ry)) ell(tint,x,y,rx,ry,{fill:light?C.sunTint:C.shadeTint,opacity:light?.22:.16,
    transform:`rotate(${f1(rot)} ${f1(x)} ${f1(y)})`});
}
if(vis(2380,80)) ell(land,480,2380,180,70,{fill:C.hill});
if(vis(5400,80)) ell(land,220,5400,160,58,{fill:C.hillHi,opacity:.35});
if(vis(9800,80)) ell(land,780,9800,170,62,{fill:C.hill});
if(vis(14060,80)) ell(land,360,14060,150,56,{fill:C.hill});
if(vis(18200,80)) ell(land,700,18200,190,64,{fill:C.hillHi,opacity:.32});

/* ---------- coast: sand, sea, waves, peninsula ---------- */
if(chunkY1>22880){
const y1=x=>23140+16*Math.sin(x/140)+8*Math.sin(x/57+2);
const y2=x=>23320+14*Math.sin(x/95+2)+7*Math.sin(x/41);
const topE=[],botE=[];
for(let x=-80;x<=1080;x+=48){topE.push([x,y1(x)]);botE.push([x,y2(x)]);}
const botD=smoothPts(botE);
path(coast,smoothPts(topE)+[...botE].reverse().map(p=>`L${f1(p[0])} ${f1(p[1])}`).join('')+'Z',{fill:C.sand});
path(coast,botD+'L1080 24020L-80 24020Z',{fill:C.sea});
path(coast,botD+`L${f1(botE[botE.length-1][0])} ${f1(botE[botE.length-1][1]+26)}`+
     [...botE].reverse().map(p=>`L${f1(p[0])} ${f1(p[1]+26)}`).join('')+'Z',{fill:C.seaLight,opacity:.9});
path(coast,botD,{stroke:'#FFFFFF','stroke-width':7,fill:'none','stroke-linecap':'round',opacity:.85});
[23476,23616,23756].forEach((wy,r2)=>{
  let d='';for(let x=-40;x<1080;x+=42)d+=`M${x} ${wy}q10.5 -12 21 0`;
  path(coast,d,{stroke:'#FFFFFF','stroke-width':3,fill:'none','stroke-linecap':'round',opacity:.42-r2*.07});
});
[[262,23204],[660,23220],[432,23252]].forEach(([sx,sy])=>{
  path(coast,`M${sx-6} ${sy}a6 6 0 0 1 12 0Z`,{fill:C.shell,stroke:C.shellEdge,'stroke-width':2});});
path(coast,blob(505,23536,88,46,.07,10),{fill:C.sandRim});
path(coast,blob(505,23510,74,36,.07,10),{fill:C.grass[0]});
ell(coast,492,23480,34,12,{fill:C.hillHi,opacity:.5});
}

/* ---------- water: streams and falls only ---------- */
function stream(pts,w){
  const sp=spline(pts.map(p=>[p[0],p[1],w]),10,true);
  path(water,sp.d,{stroke:C.waterEdge,'stroke-width':w+8,fill:'none','stroke-linecap':'round'});
  path(water,sp.d,{stroke:C.water,'stroke-width':w,fill:'none','stroke-linecap':'round'});
  sp.S.forEach(s=>waterS.push({x:s.x,y:s.y,w:w+8}));
}
function pond(cx,cy,rx,ry,o={}){
  register(cx,cy,Math.max(rx,ry)+24);
  path(water,blob(cx,cy,rx*1.12,ry*1.12,.08,12),{fill:C.waterEdge});
  path(water,blob(cx,cy,rx,ry,.08,12),{fill:C.water});
  path(water,blob(cx,cy-ry*.1,rx*.56,ry*.5,.1,10),{fill:C.waterLight,opacity:.9});
  [[-28,-8],[14,10]].forEach(([ox,oy])=>
    path(water,`M${f1(cx+ox)} ${f1(cy+oy)}q7 -6 14 0q7 6 14 0`,
      {stroke:'#E6F6FC','stroke-width':3,fill:'none','stroke-linecap':'round',opacity:.8}));
  (o.lilies||[]).forEach(([lx,ly,fl])=>{
    path(water,circSub(cx+lx,cy+ly,7),{fill:C.lily});
    path(water,`M${f1(cx+lx)} ${f1(cy+ly)}L${f1(cx+lx+9)} ${f1(cy+ly-2)}L${f1(cx+lx+8)} ${f1(cy+ly+3)}Z`,{fill:C.water});
    if(fl)path(water,circSub(cx+lx,cy+ly,2.2)+circSub(cx+lx-4,cy+ly+3,1.8)+circSub(cx+lx+4,cy+ly+3,1.8),{fill:'#F7A8C3'});
  });
  (o.reeds||[]).forEach(([rxp,ryp])=>{
    path(water,`M${f1(cx+rxp)} ${f1(cy+ryp)}L${f1(cx+rxp-3)} ${f1(cy+ryp-14)}M${f1(cx+rxp+3)} ${f1(cy+ryp)}L${f1(cx+rxp+5)} ${f1(cy+ryp-11)}`,
      {stroke:C.reed,'stroke-width':2.5,fill:'none','stroke-linecap':'round'});
    ell(water,cx+rxp-3,cy+ryp-17,2.6,6,{fill:C.reedTip});
    ell(water,cx+rxp+5,cy+ryp-14,2.4,5.5,{fill:C.reedTip});
  });
}
function waterfall(cx,cy,s=1){
  register(cx,cy,58*s);
  path(water,blob(cx-17*s,cy-16*s,17*s,11*s,.14,8),{fill:'#B6BEC1'});
  path(water,blob(cx+16*s,cy-18*s,15*s,10*s,.14,8),{fill:C.rockB});
  rrect(water,cx-13*s,cy-34*s,26*s,56*s,11*s,{fill:C.foam});
  path(water,`M${f1(cx-6*s)} ${f1(cy-30*s)}L${f1(cx-6*s)} ${f1(cy+16*s)}M${f1(cx+4*s)} ${f1(cy-28*s)}L${f1(cx+4*s)} ${f1(cy+14*s)}`,
    {stroke:'#FFFFFF','stroke-width':3*s,'stroke-linecap':'round',opacity:.85});
  ell(water,cx,cy+34*s,30*s,12*s,{fill:C.waterLight,opacity:.95});
