/* ============ flora & prop painters ============ */
function tree(x,y,s=1){
  const g=grp(flora,{class:'sway-tree'});
  g.style.animationDuration=(4.2+R(0,1.8))+'s';g.style.animationDelay=(-R(0,4))+'s';
  const c2=pick(TREE_COLS);
  ell(g,x+4*s,y+2*s,26*s,9*s,{fill:C.shadow});
  rrect(g,x-4.5*s,y-21*s,9*s,23*s,3.5*s,{fill:C.trunk});
  circ(g,x-14*s,y-32*s,17*s,{fill:c2[0]});
  circ(g,x+14*s,y-31*s,16*s,{fill:c2[0]});
  circ(g,x,y-42*s,23*s,{fill:c2[1]});
  ell(g,x-7*s,y-48*s,10*s,6*s,{fill:C.hillHi,opacity:.85});
}
function pine(x,y,s=1){
  const g=grp(flora,{class:'sway-tree'});
  g.style.animationDuration=(4.6+R(0,1.6))+'s';g.style.animationDelay=(-R(0,4))+'s';
  ell(g,x+3*s,y+2*s,18*s,6*s,{fill:C.shadow});
  rrect(g,x-3*s,y-16*s,6*s,18*s,2.5*s,{fill:C.trunk});
  const tier=(w,yy,h,col)=>path(g,`M${f1(x-w)} ${f1(yy)}L${f1(x)} ${f1(yy-h)}L${f1(x+w)} ${f1(yy)}Z`,
    {fill:col,stroke:col,'stroke-width':6*s,'stroke-linejoin':'round'});
  tier(22*s,y-8*s,28*s,C.pineA);tier(17*s,y-26*s,26*s,C.pineB);tier(12*s,y-44*s,24*s,C.pineC);tier(7.5*s,y-60*s,20*s,'#8ED176');
}
function rock(x,y,s=1){
  ell(flora,x+3*s,y+3*s,16*s,6*s,{fill:C.shadow});
  path(flora,blob(x,y-7*s,15*s,11*s,.13,8),{fill:C.rockA});
