}
function bush(x,y){
  const g=grp(flora,{class:'sway-tree'});
  g.style.animationDuration=(3.6+R(0,1.2))+'s';
  ell(g,x+2,y+2,15,6,{fill:C.shadow});
  circ(g,x-6,y-6,11,{fill:C.pineA});
  circ(g,x+6,y-5,9.5,{fill:C.pineB});
  ell(g,x-3,y-9,6,4,{fill:C.hillHi,opacity:.9});
}
function flowerPatch(x,y,k){
  const g=grp(flora,{class:'wave'});
  g.style.animationDuration=(2.1+R(0,1.5))+'s';g.style.animationDelay=(-R(0,2.6))+'s';
  const byCol=new Map();
  for(let i=0;i<k;i++){
    const fx=x+R(-27,27),fy=y+R(-19,19),col=pick(FLOWER_COLS);
    if(!byCol.has(col))byCol.set(col,{p:'',c:''});
    const o=byCol.get(col),ja=R(0,1.2);
    for(let q2=0;q2<5;q2++){const a=q2/5*6.283+ja;
      o.p+=circSub(fx+Math.cos(a)*4.4,fy+Math.sin(a)*4.4,3.3);}
    o.c+=circSub(fx,fy,2);
  }
  let blades='';
  for(let i=0;i<3;i++){const bx=x+R(-30,30),by=y+R(-20,20);
    blades+=`M${f1(bx)} ${f1(by)}l${f1(R(-2,2))} ${f1(-7)}M${f1(bx+4)} ${f1(by)}l${f1(R(-1,1))} ${f1(-9)}M${f1(bx-4)} ${f1(by)}l${f1(R(-1,1))} ${f1(-6)}`;}
  path(g,blades,{stroke:C.pineB,'stroke-width':2.2,fill:'none','stroke-linecap':'round'});
  byCol.forEach((o,col)=>{path(g,o.p,{fill:col[0]});path(g,o.c,{fill:col[1]});});
}
function butterfly(x,y){
  const g=grp(flora,{class:'flutter'});
  g.style.animationDuration=(1+R(0,.6))+'s';g.style.animationDelay=(-R(0,2))+'s';
  const col=pick([C.orange,C.gold,C.teal,C.cream]);
  ell(g,x-4,y,5,3.2,{fill:col,opacity:.95});
  ell(g,x+4,y,5,3.2,{fill:col,opacity:.85});
  rrect(g,x-1,y-2,2,6,1,{fill:C.navy});
}
