  let fd='';
  for(let yy=y0+22;yy<y0+h-10;yy+=40) fd+=`M${x0+12} ${f1(yy)}L${f1(x0+w-12)} ${f1(yy)}`;
  path(flora,fd,{stroke:C.sandRim,'stroke-width':3,'stroke-linecap':'round',opacity:.9});
  let c1='',c2='';
  for(let r2=0;r2<7;r2++){
