function bridge(b){
  const p=pathAtY(b.y), rw=riverAtY(b.y), len=rw.w+90, Wd=54;
  register(p.x,b.y,120);
  const g=grp(marks,{transform:`translate(${f1(p.x)} ${f1(b.y)}) rotate(${f1(p.ang)})`});
  ell(g,0,8,len*.42,34,{fill:C.waterShadow});
