    rrect(g,-len/2,-Wd/2,len,Wd,14,{fill:C.stoneDeck,stroke:C.stoneEdge,'stroke-width':3});
    let jl='';for(let px=-len/2+18;px<len/2-8;px+=24)jl+=`M${f1(px)} ${f1(-Wd/2+5)}L${f1(px)} ${f1(Wd/2-5)}`;
    path(g,jl,{stroke:'#C6CFCF','stroke-width':2.2,opacity:.9});
    for(const sg of[-1,1]){
      let bp='';
      for(let px=-len/2+4;px{
    const a=pts[Math.max(0,i-1)],b=pts[Math.min(pts.length-1,i+1)];
    const dx=b[0]-a[0],dy=b[1]-a[1],l=Math.hypot(dx,dy)||1;
    return [p[0]+dy/l*7,p[1]-dx/l*7];
  });
  path(fences,smoothPts(off),{stroke:'#9A6B3F','stroke-width':3.2,fill:'none','stroke-linecap':'round','stroke-linejoin':'round'});
  let pd='';for(let i=0;i{if(i%2===0)register(p[0],p[1],20);});
}
function roadFence(y0,y1,side){
  const pts=[];let last=-999;
  for(const s of pathS){
    if(s.yy1)continue;
    if(s.y-last<50)continue;
    last=s.y;pts.push([s.x+side*58,s.y]);
  }
  if(pts.length>1)fenceLine(pts);
}

