function belt(y0,y1,x0,x1,count){
  let c=0,t=0;
  while(c<count&&t<220){t++;
    const x=R(x0,x1),y=R(y0,y1);
    if(!free(x,y,30))continue;
    withVis(y,50,()=>{if(rnd()<.5)pine(x,y,R(.8,1.15));else tree(x,y,R(.85,1.2));});
    register(x,y,32);c++;
  }
}
