/* ============ stacked chunks: paint only nearby slices ============ */
const stage=document.getElementById('stage');
const slices=[];
for(let i=0;i{
  entries.forEach(e=>{
    const s=slices.find(x=>x.wrap===e.target);
    if(!s)return;
    if(e.isIntersecting) mountSlice(s); else dropSlice(s);
  });
},{root:null,rootMargin:'1400px 0px',threshold:0});
slices.forEach(s=>look.observe(s.wrap));

/* ============ Flutter / preview bridge ============ */
function notifyLevel(id){
  try{window.flutter_inappwebview?.callHandler('openLevel',id);}catch(e){}
  try{parent.postMessage({source:'quest-map',type:'openLevel',id:id},location.origin||'*');}catch(e){}
}
window.QuestMap={
  setLevels(levels){
    const stage=document.getElementById('stage');
    if(!stage||!Array.isArray(levels))return;
    stage.style.position='relative';
    let layer=document.getElementById('pins');
    if(!layer){layer=document.createElement('div');layer.id='pins';stage.appendChild(layer);}
    layer.replaceChildren();
    for(const L of levels){
      const b=document.createElement('button');
      b.type='button';
      b.className='qpin qpin-'+L.status+(L.checkpoint?' qpin-check':'');
      b.dataset.id=String(L.id);
      b.style.left=(L.x/W*100)+'%';
      b.style.top=(L.y/H*100)+'%';
      b.setAttribute('aria-label',(L.checkpoint?'Checkpoint ':'')+'Level '+L.id);
      if(L.status==='locked'){
        b.innerHTML=''+(L.checkpoint?'':'');
      }else{
        const n=Math.max(0,Math.min(3,L.stars|0));
        const stars=L.status==='completed'?`${'★'.repeat(n)}${'☆'.repeat(3-n)}`:'';
        b.innerHTML=`${L.id}${stars}`+(L.checkpoint?'':'');
      }
      b.onclick=()=>{if(L.status!=='locked') notifyLevel(L.id);};
      layer.appendChild(b);
    }
  },
  reveal(id){
    const el=document.querySelector('.qpin[data-id="'+id+'"]');
    if(el) el.scrollIntoView({block:'center',behavior:EMBED?'auto':'smooth'});
  }
};
addEventListener('message',ev=>{
  let d=ev.data;
  if(typeof d==='string'){try{d=JSON.parse(d);}catch(e){return;}}
  d=d||{};
  if(d.type==='setLevels') window.QuestMap.setLevels(d.levels);
  if(d.type==='reveal') window.QuestMap.reveal(d.id);
});

if(EMBED){
  document.getElementById('hint')?.classList.add('gone');
}else{
/* ============ page chrome: gentle auto-scroll, export ============ */
const hint=document.getElementById('hint');
let auto=!matchMedia('(prefers-reduced-motion: reduce)').matches;
function killAuto(){auto=false;hint.classList.add('gone');}
['wheel','touchstart','keydown','mousedown'].forEach(e=>addEventListener(e,killAuto,{passive:true}));
setTimeout(()=>{
  scrollTo(0, document.documentElement.scrollHeight);
  requestAnimationFrame(function step(){
    if(!auto)return;
    scrollBy(0,-1.6);
    if(scrollY>200)requestAnimationFrame(step);else killAuto();
  });
},800);

const toastEl=document.getElementById('toast');let toastT;
function toast(m){toastEl.textContent=m;toastEl.classList.add('on');
  clearTimeout(toastT);toastT=setTimeout(()=>toastEl.classList.remove('on'),2400);}
function svgString(){
  const c=document.createElementNS(NS,'svg');
  c.setAttribute('viewBox',`0 0 ${W} ${H}`);
  paintChunk(c,0,H);
  c.setAttribute('xmlns',NS);
  c.setAttribute('width','1000');c.setAttribute('height','24000');
  return new XMLSerializer().serializeToString(c);
}
function save(blob,name){
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);a.download=name;a.click();
  setTimeout(()=>URL.revokeObjectURL(a.href),4000);
}
document.getElementById('btnSvg').onclick=()=>{
  save(new Blob([svgString()],{type:'image/svg+xml'}),'quest-map.svg');
  toast('SVG saved · 1000 × 24000 vector');
};
document.getElementById('btnPng').onclick=async()=>{
  toast('Rendering PNG…');
  try{
    const url=URL.createObjectURL(new Blob([svgString()],{type:'image/svg+xml'}));
    const img=new Image();
    await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=url;});
    const cv=document.createElement('canvas');cv.width=1080;cv.height=25920;
    cv.getContext('2d').drawImage(img,0,0,1080,25920);
    URL.revokeObjectURL(url);
    cv.toBlob(b=>{if(b){save(b,'quest-map-1080x25920.png');toast('PNG saved · 1080 × 25920');}
      else toast('PNG export failed in this browser');},'image/png');
  }catch(e){toast('PNG export failed — try the SVG');}
}
}
